import{_ as r,C as s,o as n,c as i,a2 as t,E as d}from"./chunks/framework.DBKUV7en.js";const u=JSON.parse('{"title":"3. 酸っぱい・苦いの正体","description":"","frontmatter":{},"headers":[],"relativePath":"ch1/sour-bitter.md","filePath":"ch1/sour-bitter.md","lastUpdated":null}'),o={name:"ch1/sour-bitter.md"};function p(l,a,h,c,b,f){const e=s("TasteCompass");return n(),i("div",null,[a[0]||(a[0]=t('<h1 id="_3-酸っぱい・苦いの正体" tabindex="-1">3. 酸っぱい・苦いの正体 <a class="header-anchor" href="#_3-酸っぱい・苦いの正体" aria-label="Permalink to &quot;3. 酸っぱい・苦いの正体&quot;">​</a></h1><p>同じ豆を、同じレシピで淹れたはずなのに、今日はやけに酸っぱい。昨日は苦かった。</p><p>抽出においては、まず濃度と抽出率を考えます。この差を考えるときも、2つのものさしを使います。「粉からどれだけ溶け出したか」と、「できたコーヒーがどれだけ濃いか」です。先に答えを言っておくと、苦い日は、まず<strong>濃すぎ</strong>を疑います。酸っぱい日は、出きっていないか、濃すぎのどちらかです。</p><p>この回は、抽出の話です。</p><h2 id="コーヒーは、粉から溶かし出した液体" tabindex="-1">コーヒーは、粉から溶かし出した液体 <a class="header-anchor" href="#コーヒーは、粉から溶かし出した液体" aria-label="Permalink to &quot;コーヒーは、粉から溶かし出した液体&quot;">​</a></h2><p>お湯をかけると、粉の中の成分が少しずつお湯に溶けていきます。これを抽出といいます。</p><p>ここで出てくるのが、2つのものさしです。1つは<strong>抽出率</strong>で、粉の重さのうち何%が溶け出したか。もう1つは濃度で、できた液の中に成分が何%溶けているか(正式にはTDSと呼びます)。</p><p>この2つは別々に動きます。たくさん溶け出していても、お湯が多ければ薄くなる。逆に、あまり溶けていなくても、お湯が少なければ濃くなります。この話は<a href="/coffee-textbook/ch1/strength-vs-extraction">第4回</a>でもう少し詳しく書きます。</p><h2 id="_12人が27通りを飲み比べた研究" tabindex="-1">12人が27通りを飲み比べた研究 <a class="header-anchor" href="#_12人が27通りを飲み比べた研究" aria-label="Permalink to &quot;12人が27通りを飲み比べた研究&quot;">​</a></h2><p>2020年に、アメリカのUC Davisのチームが、この2つと味の関係を調べています。ホンジュラスの豆を1種類使い、業務用のドリップの機械で、濃度と抽出率を3段階ずつ変えて淹れました。湯温も3通り変えたので、全部で27通りです。それを、訓練を受けた12人のテイスターが飲み比べています。</p><p>結果はこうでした。濃度が上がると、苦さ、渋さ、口当たりの重さが強くなりました。意外だったのは、酸っぱさも濃度と一緒に強くなったことです。一方で、抽出率が上がると、酸っぱさや柑橘っぽさは弱まって、紅茶のような感じが出てきました。</p><p>そして、2つのうち味への効き方が大きかったのは、<strong>濃度</strong>のほうでした。</p><p>豆1種類での研究なので、浅煎りで同じ結果になるかは分かっていません。詳しい条件は<a href="/coffee-textbook/appendix/studies">付録</a>に置いています。</p><h2 id="「出すぎると渋い」は本当" tabindex="-1">「出すぎると渋い」は本当? <a class="header-anchor" href="#「出すぎると渋い」は本当" aria-label="Permalink to &quot;「出すぎると渋い」は本当?&quot;">​</a></h2><p>抽出率が22%を超えると苦くて渋くなる、とよく言われます。でもこの研究では、24%まで抽出率を上げても、苦さや渋さとはっきり結びついていたのは濃度のほうでした。抽出率が高いと苦さが少し増える、という別の研究もあって、ここは研究によって結果が少し違います。</p><p>もう1つ、「出すぎ」と言われている味の多くは、実はムラ(一部の粉は出すぎて、一部は出きっていない状態)のせいだ、という説明もよく見かけます。ただ、これを味で確かめた研究は見つかりませんでした。</p><p>なので僕は、渋い・えぐいと感じたら、まず濃すぎを疑って、それでも残るならムラを疑うようにしています。ムラの話は第7回<span class="soon">(準備中)</span>で書きます。</p><h2 id="「酸っぱい」と「酸味」は、ちょっと違う" tabindex="-1">「酸っぱい」と「酸味」は、ちょっと違う <a class="header-anchor" href="#「酸っぱい」と「酸味」は、ちょっと違う" aria-label="Permalink to &quot;「酸っぱい」と「酸味」は、ちょっと違う&quot;">​</a></h2><p>同じ「すっぱい」でも、印象は2つに分かれると思っています。とがっていて、後味が薄くて物足りないもの。これは抽出で直せることが多いです。もう1つは、果物みたいに明るくて、甘さや香りと一緒にくるもの。こちらは豆の個性です。</p><p>浅煎りの豆は、もともとこの「明るい酸味」を持っています。だから浅煎りで酸っぱいと感じても、全部が抽出のせいとは限りません。この分け方は研究で決まったものではなく、僕の整理です。研究で分かっているのは、抽出率を上げると酸っぱさが弱まる、というところまでです。</p><p>ちなみに、「クエン酸は柑橘、リンゴ酸はリンゴ」のように酸を1つずつ言い分けるのは、専門家でも難しいようです。2023年の研究では、コーヒーの専門家13人の誰も、コーヒーに足した酸の種類を当てられませんでした。なのでこの教科書では、酸は「全体の酸味」として扱います。浅煎りの話は第9回<span class="soon">(準備中)</span>で続けます。</p><h2 id="味から、次の一手を決める" tabindex="-1">味から、次の一手を決める <a class="header-anchor" href="#味から、次の一手を決める" aria-label="Permalink to &quot;味から、次の一手を決める&quot;">​</a></h2><p>ここまでの話を、ドリップグリッドで見るとこうなります。</p>',23)),d(e,{highlight:"left"}),a[1]||(a[1]=t('<p>見る順番は、まず縦(濃度)、次に横(抽出)。研究で濃度のほうが効いていたので、そこから疑うのが近道だと思っています。</p><table tabindex="0"><thead><tr><th>感じた味</th><th>図のどこか</th><th>まず変えること(1つだけ)</th></tr></thead><tbody><tr><td>苦い・渋い・重い</td><td>上(濃い)</td><td>お湯を少し増やす(または粉を減らす)</td></tr><tr><td>酸っぱくて、しかも濃い</td><td>上(濃い)</td><td>まず濃度を下げる</td></tr><tr><td>酸っぱい・とがった感じ</td><td>左(出きっていない)</td><td>挽き目を少し細かくする</td></tr><tr><td>濃度を下げても渋い</td><td>ムラかも</td><td>第7回へ</td></tr><tr><td>水っぽい・軽い</td><td>下(薄い)</td><td>粉を少し増やす(またはお湯を減らす)</td></tr></tbody></table><div class="tip custom-block"><p class="custom-block-title">変えるのは1回に1つだけ</p><p>挽き目とお湯の量を一緒に変えると、どっちが効いたのか分からなくなります。第5回<span class="soon">(準備中)</span>で、つまみごとの動き方を詳しく書きます。</p></div><p>比べるときは、飲む温度もそろえるのがおすすめです。熱いときと冷めたときで、酸っぱさの感じ方が変わる、という研究があります。これは第22回<span class="soon">(準備中)</span>で詳しく書きます。</p><h2 id="準備中" tabindex="-1">(準備中...) <a class="header-anchor" href="#準備中" aria-label="Permalink to &quot;(準備中...)&quot;">​</a></h2><p>挽き目だけを変えて浅煎りを淹れ比べる実験を、第10回<span class="soon">(準備中)</span>でやる予定です。味見の温度だけを変える実験も考えています。やったら、結果と動画をここに足します。</p><h2 id="確かさの一覧" tabindex="-1">確かさの一覧 <a class="header-anchor" href="#確かさの一覧" aria-label="Permalink to &quot;確かさの一覧&quot;">​</a></h2><details class="details custom-block"><summary>表を開く</summary><table tabindex="0"><thead><tr><th>書いたこと</th><th>確かさ</th></tr></thead><tbody><tr><td>濃度が上がると苦い・渋い・重い、酸っぱさも強まる。抽出率が上がると酸っぱさは弱まる。効き方は濃度のほうが大きい</td><td><span class="stamp stamp-research ignore-header" tabindex="0" data-tip="研究(論文や学会発表)で確かめられている" aria-label="研究: 研究(論文や学会発表)で確かめられている">研究</span> Batali ら 2020(ホンジュラス産1種・ドリップ・12人)。浅煎りで同じかは <span class="stamp stamp-unverified ignore-header" tabindex="0" data-tip="まだ確かめられていない" aria-label="未確認: まだ確かめられていない">未確認</span></td></tr><tr><td>抽出率が高いと苦さが少し増える</td><td><span class="stamp stamp-research ignore-header" tabindex="0" data-tip="研究(論文や学会発表)で確かめられている" aria-label="研究: 研究(論文や学会発表)で確かめられている">研究</span> Frost ら 2020 の傾向。Batali ら 2020 では有意ではなかった</td></tr><tr><td>渋い・えぐいの多くはムラのせい</td><td><span class="stamp stamp-unverified ignore-header" tabindex="0" data-tip="まだ確かめられていない" aria-label="未確認: まだ確かめられていない">未確認</span> よく言われるが、味で確かめた研究は見つかっていない</td></tr><tr><td>「酸っぱい」と「酸味」の分け方</td><td><span class="stamp stamp-reasoning ignore-header" tabindex="0" data-tip="計算や、情報をつなげて考えたこと。研究そのものではない" aria-label="考察: 計算や、情報をつなげて考えたこと。研究そのものではない">考察</span> 考察。研究が直接分けたものではない</td></tr><tr><td>専門家13人でも、コーヒーの酸の種類を当てられなかった</td><td><span class="stamp stamp-research ignore-header" tabindex="0" data-tip="研究(論文や学会発表)で確かめられている" aria-label="研究: 研究(論文や学会発表)で確かめられている">研究</span> Rune ら 2023</td></tr><tr><td>飲む温度で酸っぱさの感じ方が変わる</td><td><span class="stamp stamp-research ignore-header" tabindex="0" data-tip="研究(論文や学会発表)で確かめられている" aria-label="研究: 研究(論文や学会発表)で確かめられている">研究</span> Steen ら 2017(1品種・31〜62℃。要旨のみ確認)。ほかの研究と食い違う面もある <span class="stamp stamp-unverified ignore-header" tabindex="0" data-tip="まだ確かめられていない" aria-label="未確認: まだ確かめられていない">未確認</span></td></tr><tr><td>まず濃度、次に抽出を見る順番</td><td><span class="stamp stamp-reasoning ignore-header" tabindex="0" data-tip="計算や、情報をつなげて考えたこと。研究そのものではない" aria-label="考察: 計算や、情報をつなげて考えたこと。研究そのものではない">考察</span> 考察(研究で濃度の効き方が大きかったことから)</td></tr></tbody></table></details><h2 id="出典" tabindex="-1">出典 <a class="header-anchor" href="#出典" aria-label="Permalink to &quot;出典&quot;">​</a></h2><ul><li>Batali, Ristenpart, Guinard (2020) <em>Brew temperature, at fixed brew strength and extraction, has little impact on the sensory profile of drip brew coffee</em>. Scientific Reports. <a href="https://pmc.ncbi.nlm.nih.gov/articles/PMC7536440/" target="_blank" rel="noreferrer">PMC</a></li><li>Frost ら (2020) Journal of Food Science。<a href="https://sca.coffee/sca-news/25/issue-13/towards-a-new-brewing-chart-xpj8t" target="_blank" rel="noreferrer">SCAの解説記事</a></li><li>Rune ら (2023) Current Research in Food Science(コーヒーの酸と焙煎度)。<a href="https://pmc.ncbi.nlm.nih.gov/articles/PMC10074501" target="_blank" rel="noreferrer">PMC</a></li><li>Steen ら (2017) Food Chemistry(提供温度と味)。<a href="https://pubmed.ncbi.nlm.nih.gov/27765259/" target="_blank" rel="noreferrer">PubMed</a>(要旨のみ確認)</li><li>「出すぎ」とムラの一般的な説明: Wikipedia <a href="https://en.wikipedia.org/wiki/Coffee_extraction" target="_blank" rel="noreferrer">Coffee extraction</a>、<a href="https://beanbench.coffee/learn/coffee-extraction/" target="_blank" rel="noreferrer">BeanBench</a>(解説サイト)</li></ul><p>次は、<a href="/coffee-textbook/ch1/strength-vs-extraction">4. 「濃い」と「よく出ている」は別の話</a>です。</p>',11))])}const _=r(o,[["render",p]]);export{u as __pageData,_ as default};
